[**[AGC034D] Manhattan Max Matching**](https://www.luogu.com.cn/problem/AT_agc034_d)

容易想到建出图跑费用流，但是有$n^2$条边，这时有一个 $Trick$ ，考虑曼哈顿距离的形式。

$d_{i,j}=|x_i-x_j|+|y_i-y_j|$

$=max(x_i-x_j+y_i-y_j,-x_i+x_j+y_i-y_j,x_i-x_j-y_i+y_j,-x_i+x_j-y_i+y_j)$

$=max((x_i+y_i)+(-x_j-y_j),(-x_i+y_i)+(x_j-y_j),(x_i-y_i)+(-x_j+y_j),(-x_i-y_i)+(x_j+y_j))$

然后因为原题也在求 $max$ ,所以两个 $max$ 可以合在一起

所以建出二分图后，中间再建四个点依次连边即可


```cpp
#include<bits/stdc++.h>
#define LL long long
//#define FILE
#define inf 1e9
using namespace std;
int n,s,t;
struct edge
{
    int to,nxt,val,dis;
}e[100005];
int tot=1,head[5005];
void add(int u,int v,int w,int c)
{
    e[++tot].nxt=head[u];
    e[tot].to=v,e[tot].val=w,e[tot].dis=c;
    head[u]=tot;
}
void addx(int u,int v,int w,int c){add(u,v,w,c),add(v,u,0,-c);}
int rev[5005];
LL flow[5005],dis[5005];
bool vis[5005];
queue<int> q;
pair<LL,LL> min_cost(int s,int t)
{
    LL res=0,sum=0;
    while (1)
    {
        memset(dis,0x3f,sizeof dis);
        memset(vis,0,sizeof vis);
        flow[s]=1e18,dis[s]=0,q.push(s);
        while (!q.empty())
        {
            int u=q.front();
            q.pop(),vis[u]=0;
            for (int i=head[u];i;i=e[i].nxt)
            {
                int v=e[i].to,w=e[i].val,c=e[i].dis;
                if (w&&dis[u]+c<dis[v])
                {
                    flow[v]=min(flow[u],w*1ll);
                    dis[v]=dis[u]+c;rev[v]=i;
                    if (!vis[v]) q.push(v),vis[v]=1;
                }
            }
        }
        if (dis[t]>1e18) return make_pair(res,sum);
        sum+=dis[t]*flow[t];
        res+=flow[t];
        for (int i=t;i!=s;i=e[rev[i]^1].to)	e[rev[i]].val-=flow[t],e[rev[i]^1].val+=flow[t];
    }
}
signed main()
{
    #ifdef FILE
    freopen(".in","r",stdin);
    freopen(".out","w",stdout);
    #endif
    scanf("%d",&n);
    int p1=2*n+1,p2=p1+1,p3=p2+1,p4=p3+1;s=p4+1,t=s+1;
    for (int i=1;i<=n;i++)
    {
        int x,y,z;
        scanf("%d%d%d",&x,&y,&z);
        addx(s,i,z,0);
        addx(i,p1,inf,x+y),addx(i,p2,inf,x-y),addx(i,p3,inf,-x+y),addx(i,p4,inf,-x-y);
    }
    for (int i=1;i<=n;i++)
    {
        int x,y,z;
        scanf("%d%d%d",&x,&y,&z);
        addx(i+n,t,z,0);
        addx(p1,i+n,inf,-x-y),addx(p2,i+n,inf,-x+y),addx(p3,i+n,inf,x-y),addx(p4,i+n,inf,x+y);
    }
    printf("%lld",-min_cost(s,t).second);

    return 0;
}
```

[**[AGC022E] Median Replace**](https://www.luogu.com.cn/problem/AT_agc022_e)

考虑如何判定一个序列合法

观察发现如果操作的三个数不相同，整个序列 $1$ 和 $0$ 的相对个数不改变 , 可以看成不同的两个数相抵消。

而操作相同的三个数时，这个数的总数减 $2$ 。

所以只要某个时刻 $1$ 的个数比 $0$ 多即可。所以策略应该是尽量多使得三个 $0$ 连在一起被消掉，考虑用栈模拟这个过程

可以得到：

- 如果当前是 $0$，前面连着两个 $0$ 就可以把前面两个 $0$ 消掉
- 如果当前是 $0$，前面是 $1$，则先不消，因为不知道后面是否有$ 0$
- 如果当前是 $1$，前面是 $0$，那么前面连着 $0$ 的个数一定 $\leq2$ 。若个数为 $2$ ，则当前 $1$与前一个 $0$ 抵消后，前一个 $0$ 还有与后面的 $0$ 的抵消的可能。若个数不为 $2$ ，消除后也无影响，并且发现这样可以使得栈中栈顶到栈底是一段连续的 $0$ 和一段连续的 $1$ 。
- 如果当前是 $1$ ，前面是 $1$ ，由于 $0$ 的个数 $\leq2$ ，所以保留最多 $2$ 个 $1$ 即可。

用 $f_{i,j,k}$ 表示前 $i$ 个数的栈中有 $j$ 个 $0$ , $k$ 个 $1$ ，按上面转移即可。


```cpp
#include <bits/stdc++.h>
using namespace std;
#define ll long long
//#define LOCAL
constexpr ll mo=1e9+7;
char s[300005];
int n;
ll f[300005][3][3]; 
signed main()
{
	#ifdef LOCAL
	freopen(".in","r",stdin);
	freopen(".out","w",stdout);
	#endif
	scanf("%s",s+1);n=strlen(s+1);
	f[0][0][0]=1;
	for (int i=1;i<=n;i++)
	{
		if (s[i]!='1')
			for (int j=0;j<=2;j++) f[i][1][j]=(f[i-1][0][j]+f[i-1][2][j])%mo,f[i][2][j]=f[i-1][1][j];
		if (s[i]!='0')
		{
			f[i][0][1]=f[i-1][0][0],f[i][0][2]=(f[i-1][0][1]+f[i-1][0][2])%mo;
			for (int j=1;j<=2;j++) 
				for (int k=0;k<=2;k++) f[i][j-1][k]=(f[i][j-1][k]+f[i-1][j][k])%mo;
		}
	}
	ll ans=0;
	for (int i=0;i<=2;i++)
		for (int j=i;j<=2;j++) ans=(ans+f[n][i][j])%mo;
	printf("%lld\n",ans); 
	return 0;
}
/**/

```

